def bootstrap_categories_and_clean_orphans(apps, schema_editor):
    DeviceCategory = apps.get_model('router_manager', 'DeviceCategory')
    RouterGroup = apps.get_model('router_manager', 'RouterGroup')
    RouterClient = apps.get_model('router_manager', 'RouterClient')
    Router = apps.get_model('router_manager', 'Router')

    cat_nodos, _ = DeviceCategory.objects.get_or_create(name='Nodos', defaults={'position': 1})
    cat_clientes, _ = DeviceCategory.objects.get_or_create(name='Clientes', defaults={'position': 2})

    # 1. Vincular todos los grupos existentes a la categoría Nodos
    for grp in RouterGroup.objects.filter(category__isnull=True).order_by('id'):
        clean_name = re.sub(r'\s+', ' ', (grp.name or '').strip()).upper() or f'GRUPO_{grp.id}'
        existing = RouterGroup.objects.filter(category=cat_nodos, name=clean_name).exclude(pk=grp.pk).first()
        if existing:
            for r in grp.routers.all():
                existing.routers.add(r)
            grp.delete()
        else:
            grp.name = clean_name
            grp.category = cat_nodos
            grp.save(update_fields=['name', 'category'])

    # 2. Migrar Clientes existentes (RouterClient) como Grupos dentro de la categoría Clientes
    for cli in RouterClient.objects.all().order_by('id'):
        clean_name = re.sub(r'\s+', ' ', (cli.name or '').strip()).upper() or f'CLIENTE_{cli.id}'
        target_grp, _ = RouterGroup.objects.get_or_create(
            category=cat_clientes,
            name=clean_name,
            defaults={'internal_notes': cli.internal_notes or ''}
        )
        for r in cli.routers.all():
            for other_g in RouterGroup.objects.filter(routers=r).exclude(pk=target_grp.pk):
                other_g.routers.remove(r)
            target_grp.routers.add(r)

    # 3. Eliminar cualquier dispositivo huérfano sin grupo asignado ("SIN NODO ASIGNADO")
    for orphan in Router.objects.filter(routergroup__isnull=True):
        prof = orphan.backup_profile
        if prof and prof.name.startswith('Perfil Automático -'):
            orphan.backup_profile = None
            orphan.save(update_fields=['backup_profile'])
            if prof.router_set.count() == 0:
                prof.delete()
        orphan.delete()


